-- ===== Muhammad al-Xorazmiy =====
UPDATE fact_cards SET topic_ru = 'Моя родина', question_ru = 'Где родился Мухаммад аль-Хорезми и почему его так называют?', fact_ru = 'Я родился в краю Хорезм — оттого меня и зовут аль-Хорезми. Большая часть моей жизни прошла в багдадском «Байт уль-хикма» — Доме мудрости.' WHERE id = 146;
UPDATE fact_cards SET topic_ru = 'Алгебра', question_ru = 'Из какого труда аль-Хорезми произошло слово «алгебра»?', fact_ru = 'В труде «Аль-китаб аль-мухтасар фи хисаб аль-джабр валь-мукабала» я изложил правила решения уравнений. От слова «аль-джабр» в его названии произошёл термин «алгебра».' WHERE id = 147;
UPDATE fact_cards SET topic_ru = 'Слово «алгоритм»', question_ru = 'Как появилось слово «алгоритм»?', fact_ru = 'Моё имя было передано на латыни как «Algoritmi». Поэтому последовательность правил вычисления сегодня называют «алгоритмом».' WHERE id = 148;
UPDATE fact_cards SET topic_ru = 'Индийские цифры', question_ru = 'Как аль-Хорезми познакомил мир с индийскими цифрами и нулём?', fact_ru = 'Я объяснил индийские цифры и десятичную систему счисления, в том числе ноль. Через этот труд цифры разошлись по Европе, и сегодня их называют «арабскими».' WHERE id = 149;
UPDATE fact_cards SET topic_ru = 'География', question_ru = 'Как называется труд аль-Хорезми по географии?', fact_ru = 'В труде «Китаб сурат аль-ард» я привёл координаты городов и рек, известных в то время.' WHERE id = 150;
UPDATE fact_cards SET topic_ru = 'Моё руководство «Байт уль-хикма»', question_ru = 'Какую должность занимал Мухаммад аль-Хорезми в Багдаде?', fact_ru = 'При халифе Мамуне я руководил учёными багдадского «Байт уль-хикма» — Дома мудрости — и заведовал его библиотекой.' WHERE id = 1495;
UPDATE fact_cards SET topic_ru = 'Мои таблицы «Зидж»', question_ru = 'Как называется книга астрономических таблиц Мухаммада аль-Хорезми?', fact_ru = 'Я составил труд по астрономии под названием «Зидж». В нём даны таблицы движения Солнца, Луны и планет, а также таблица синусов.' WHERE id = 1496;
UPDATE fact_cards SET topic_ru = 'Ноль и слово «сифр»', question_ru = 'Что означает слово «сифр», которым пользовался аль-Хорезми?', fact_ru = 'Для обозначения пустого разряда в счёте мы использовали арабское слово «сифр» — «пустой». Это название нуля впоследствии перешло и в другие языки.' WHERE id = 1497;
UPDATE fact_cards SET topic_ru = 'Задачи повседневной жизни', question_ru = 'Для каких практических задач аль-Хорезми написал книгу по алгебре?', fact_ru = 'Свою книгу по алгебре я написал для задач, нужных людям в повседневной жизни: раздел наследства, измерение земли и торговые расчёты — в их числе.' WHERE id = 1498;
UPDATE fact_cards SET topic_ru = 'Мои труды об астролябии', question_ru = 'О каком астрономическом приборе аль-Хорезми написал труды?', fact_ru = 'Я написал труды об астролябии — приборе для измерения высоты звёзд. В них изложены способы изготовления прибора и работы с ним.' WHERE id = 1499;
UPDATE fact_cards SET topic_ru = 'Измерение окружности Земли', question_ru = 'В каком крупном измерении участвовал аль-Хорезми при халифе Мамуне?', fact_ru = 'По поручению халифа Мамуна учёные измерили длину окружности Земли. Я тоже участвовал в этих научных работах.' WHERE id = 1500;
UPDATE fact_cards SET topic_ru = 'Кратер на Луне', question_ru = 'Какой объект на Луне назван именем Мухаммада аль-Хорезми?', fact_ru = 'Один из кратеров на обратной стороне Луны назван моим именем. Это знак уважения к труду учёных.' WHERE id = 1501;
UPDATE fact_cards SET topic_ru = 'Университет моего имени', question_ru = 'Какой университет в Ташкенте назван именем Мухаммада аль-Хорезми?', fact_ru = 'Ташкентский университет информационных технологий носит моё имя. И это не случайно: компьютерные программы работают на основе алгоритмов.' WHERE id = 1502;
UPDATE fact_cards SET topic_ru = 'Мой 1200-летний юбилей', question_ru = 'В каком году отмечалось 1200-летие со дня рождения аль-Хорезми?', fact_ru = 'Я умер в 850 году. Много веков спустя, в 1983 году, широко отмечалось 1200-летие со дня моего рождения. По этому случаю в родном Хорезме мне поставили памятник. То, что земляки меня не забыли, наполняет моё сердце теплом.' WHERE id = 1503;
UPDATE fact_cards SET topic_ru = 'В европейских учебниках', question_ru = 'Как книга аль-Хорезми по алгебре послужила Европе?', fact_ru = 'Мою книгу по алгебре перевели на латынь, и веками её преподавали в европейских университетах как учебник математики.' WHERE id = 1504;
UPDATE fact_cards SET topic_ru = 'Карта тысячи звёзд', question_ru = 'Сколько звёзд изучил аль-Хорезми?', fact_ru = 'Я наблюдал более тысячи звёзд и составил карту их расположения.' WHERE id = 1850;
UPDATE fact_cards SET topic_ru = 'Обсерватория в Багдаде', question_ru = 'Что построил аль-Хорезми в Багдаде?', fact_ru = 'Вместе с Ахмадом аль-Фергани я руководил строительством обсерватории в Багдаде.' WHERE id = 1851;
UPDATE fact_cards SET topic_ru = '«Мафатих аль-улум»', question_ru = 'Из скольких томов состоит «Мафатих аль-улум»?', fact_ru = 'Мой труд «Мафатих аль-улум» состоит из девяти томов.' WHERE id = 1852;
UPDATE fact_cards SET topic_ru = 'Мои трактаты о музыке и истории', question_ru = 'Занимался ли аль-Хорезми только математикой?', fact_ru = 'Кроме математики я написал также трактат о музыке и трактат по истории.' WHERE id = 1853;
UPDATE fact_cards SET topic_ru = 'Мой труд о солнечных часах', question_ru = 'Писал ли аль-Хорезми об измерении времени?', fact_ru = 'Я написал отдельный труд о солнечных часах.' WHERE id = 1854;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер аль-Хорезми?', fact_ru = 'Я скончался в 850 году в городе Багдад.' WHERE id = 1855;

-- ===== Abu Ali ibn Sino =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абу Али ибн Сина?', fact_ru = 'Я родился в 980 году в селении Афшана близ Бухары.' WHERE id = 156;
UPDATE fact_cards SET topic_ru = '«Канон врачебной науки»', question_ru = 'Что за труд «Канон врачебной науки» Ибн Сины?', fact_ru = 'Мой труд «Аль-Канун фи-т-тибб» из пяти книг привёл в систему болезни, лекарства и способы лечения. Веками он служил учебником в европейских университетах.' WHERE id = 157;
UPDATE fact_cards SET topic_ru = 'Знание в юности', question_ru = 'В каком возрасте Ибн Сина начал заниматься врачеванием?', fact_ru = 'В шестнадцать лет я начал заниматься врачеванием и получил право пользоваться библиотекой бухарского эмира.' WHERE id = 158;
UPDATE fact_cards SET topic_ru = '«Книга исцеления»', question_ru = 'Каким наукам посвящена «Книга исцеления» Ибн Сины?', fact_ru = 'Этот мой труд — не о медицине, а энциклопедия философии, логики и естественных наук.' WHERE id = 159;
UPDATE fact_cards SET topic_ru = 'Заразные болезни', question_ru = 'Что Ибн Сина писал о заразных болезнях?', fact_ru = 'Я писал, что некоторые болезни передаются через воду и воздух, и советовал отделять больных от здоровых.' WHERE id = 160;
UPDATE fact_cards SET topic_ru = 'Моё имя в Европе', question_ru = 'Под каким именем Абу Али ибн Сина известен в Европе?', fact_ru = 'В Европе меня называют «Авиценна». Мои труды перевели на латынь, и они учили тамошних врачей.' WHERE id = 1630;
UPDATE fact_cards SET topic_ru = 'Как я вылечил эмира', question_ru = 'Какого правителя Ибн Сина вылечил в юности и что получил взамен?', fact_ru = 'В юности я вылечил бухарского эмира Нуха ибн Мансура. В благодарность мне разрешили пользоваться богатой дворцовой библиотекой.' WHERE id = 1631;
UPDATE fact_cards SET topic_ru = 'Мой наставник Натили', question_ru = 'Кто был наставником Ибн Сины в детстве?', fact_ru = 'В детстве учёный Абу Абдуллах Натили обучал меня логике и другим наукам. Вскоре я своими вопросами удивлял и самого наставника.' WHERE id = 1632;
UPDATE fact_cards SET topic_ru = 'Помощь книги Фараби', question_ru = 'С помощью чьей книги Ибн Сина понял «Метафизику» Аристотеля?', fact_ru = 'Я перечитывал «Метафизику» Аристотеля снова и снова и не мог понять. Когда мне в руки попала книга-комментарий Абу Насра аль-Фараби, всё прояснилось.' WHERE id = 1633;
UPDATE fact_cards SET topic_ru = 'Мой труд «Донишнаме»', question_ru = 'Какой крупный труд Ибн Сина написал на персидском языке?', fact_ru = 'На персидском языке я написал труд под названием «Донишнаме». В нём я простым языком изложил философию, логику и естественные науки.' WHERE id = 1634;
UPDATE fact_cards SET topic_ru = 'Моя медицинская поэма', question_ru = 'Какое стихотворное сочинение по медицине написал Ибн Сина?', fact_ru = 'Чтобы медицину было легче заучивать, я написал стихотворное сочинение «Урджуза». В нём правила лечения изложены стихами.' WHERE id = 1635;
UPDATE fact_cards SET topic_ru = 'Моя книга о сердечных лекарствах', question_ru = 'Какой труд Ибн Сина написал о сердечных лекарствах?', fact_ru = 'Я написал особый трактат о сердечных лекарствах. В нём объяснил, какие снадобья укрепляют сердце и как настроение влияет на здоровье.' WHERE id = 1636;
UPDATE fact_cards SET topic_ru = 'Диагноз по пульсу', question_ru = 'Каким способом Ибн Сина ставил больным диагноз?', fact_ru = 'Внимательно вслушиваясь в биение пульса больного, я определял причину болезни. Я писал, что пульс говорит даже о чувствах человека.' WHERE id = 1637;
UPDATE fact_cards SET topic_ru = 'Моё визирство в Хамадане', question_ru = 'На какой должности работал Ибн Сина в Хамадане?', fact_ru = 'Часть жизни я провёл в городе Хамадан: там я лечил правителя и служил в должности визиря.' WHERE id = 1638;
UPDATE fact_cards SET topic_ru = 'Мой мавзолей', question_ru = 'В каком городе находится мавзолей Ибн Сины?', fact_ru = 'Мой мавзолей находится в городе Хамадан. Посмотреть на него приезжают люди со всех концов света.' WHERE id = 1639;
UPDATE fact_cards SET topic_ru = 'Как я выучил Коран', question_ru = 'В каком возрасте Ибн Сина выучил Коран наизусть?', fact_ru = 'Не достигнув десяти лет, я уже знал Коран наизусть целиком.' WHERE id = 1842;
UPDATE fact_cards SET topic_ru = 'Моя слава в шестнадцать лет', question_ru = 'В каком возрасте Ибн Сина стал известным врачом?', fact_ru = 'В шестнадцать лет я был уже известным врачом.' WHERE id = 1843;
UPDATE fact_cards SET topic_ru = 'Число моих трудов', question_ru = 'Сколько трудов написал Ибн Сина и сколько из них сохранилось?', fact_ru = 'По разным наукам я написал более 450 трудов. Из них до наших дней дошли 242.' WHERE id = 1844;
UPDATE fact_cards SET topic_ru = 'Какими науками я занимался', question_ru = 'Какими науками занимался Ибн Сина?', fact_ru = 'Я занимался астрономией, философией, математикой, физикой, химией, медициной, логикой, литературой и минералогией.' WHERE id = 1845;
UPDATE fact_cards SET topic_ru = 'Мои странствия по городам', question_ru = 'В каких городах жил Ибн Сина?', fact_ru = 'С 1002 года я жил и творил в Ургенче, Абиварде, Насе, Нишапуре, Джурджане, Рее, Исфахане и Хамадане.' WHERE id = 1846;
UPDATE fact_cards SET topic_ru = 'Строение «Канона»', question_ru = 'Из скольких книг и томов состоит «Канон врачебной науки»?', fact_ru = 'Мой труд «Китаб аль-канун фи-т-тибб» состоит из пяти книг и четырнадцати томов.' WHERE id = 1847;
UPDATE fact_cards SET topic_ru = 'Мои труды по разным наукам', question_ru = 'Есть ли у Ибн Сины труды о музыке и литературе?', fact_ru = 'У меня четыре труда по литературе, пять — по музыке и более десяти — по астрономии.' WHERE id = 1848;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Ибн Сина?', fact_ru = 'Я скончался в 1037 году, в пятьдесят семь лет, в городе Хамадан.' WHERE id = 1849;
